            workspace: workspace,
            repository: repository,
            checkRunId: checkRunId,
            status: 'completed',
            conclusion: job.conclusion,
            title: checkName + ' — ' + job.conclusion + ' (mirrored from run ' + runId + ')',
            summary: 'Mirrored from [workflow run ' + runId + '](' +
                (job.html_url || '') + '): job `' + jobName + '` concluded `' +
                job.conclusion + '`.'
