            summary.missing.push({ name: checkName, jobName: jobName });
            continue;
        }
        if (job.status !== 'completed' || !job.conclusion) {
            summary.skipped.push({ name: checkName, jobName: jobName, reason: 'not-completed', jobStatus: job.status });
