                workspace: owner, repository: repo, commitSha: pr.head.sha
            })) || {};
            rollup = (cr.check_runs || []).map(function (r) {
                return {
                    name: r.name || null,
                    conclusion: r.conclusion ? String(r.conclusion).toUpperCase() : null,
                    status: r.status ? String(r.status).toUpperCase() : null
