    assert.ok(cancels[0].indexOf('/actions/runs/111/cancel') !== -1, 'run 111 (old head, this branch)');
    var dispatch = sm.capturedCliCommands.filter(function (c) {
        return c.command.indexOf('workflow run ci.yml') !== -1; });
