    var CUR = 'cccc1111cccc1111cccc1111cccc1111cccc1111';
    var sm = makeSmAgent(Object.assign(config('IstiN', 'flutter_agent_harness'), {
        github: { items: [prItem(82, { branch: 'ai/gh-77', headSha: CUR })] },
