            }
            if (st === 'completed') {
                var concl = state.conclusion ? String(state.conclusion).toLowerCase() : null;
                if (concl === 'cancelled') {
                    out.zombies.push({ name: (cr && cr.name) || null, runId: runId, reason: 'cancelled' });
                    return;
                }
                if (concl) {
                    var endTs = Date.parse(state.updated_at || state.updated_at ||
                                           state.created_at || '');
