    var sm = makeSmAgent(Object.assign(config('IstiN', 'flutter_agent_harness'), {
        github: { items: [prItem(76, { branch: 'ai/gh-9' })] }
    }));
    sm.action({ jobParams: { owner: 'IstiN', repo: 'flutter_agent_harness',
