var RUN_GREEN = '38057801418';          // the 13:58 green run (fa #1457)
var RUN_DEAD = '38099999999';           // the cancelled-then-deleted run
var RUN_LIVE = '38111111111';           // a genuinely in-flight run

function cr(extra) {
