        ];
        var map = {};
        map[RUN_GREEN] = { id: RUN_GREEN, status: 'completed', conclusion: 'success',
                           updated_at: '2026-10-10T13:58:00Z' };
        var out = cz.classify(checkRuns, resolver(map, {}), NOW, {});
        assert.equal(out.zombies.length, 2);
        assert.equal(out.settled, 2);
