              details_url: 'https://github.com/IstiN/flutter_agent_harness/actions/runs/' + LIVE_RUN }
        ] };
        var sm = makeSmAgent(Object.assign(config('IstiN', 'flutter_agent_harness'), {
            github: { items: [prItem(86, { branch: 'ai/gh-86', headSha: CUR,
