                    return { workflow_runs: [
                        { id: 38057801418, event: 'workflow_dispatch', head_branch: 'ai/gh-86',
                          head_sha: CUR, status: 'completed', conclusion: 'success',
                          created_at: '2026-10-10T13:58:00Z' },
